"""Narrative of report 15 (Milestone 10: one learned controller competitive or better across the board, plant v3; ADR 0010).
Result sections are filled from runs/m10/metrics_test.json."""
import os as _os
from pathlib import Path

from experiments.d7_extras import LABELS, load
from experiments.m10_extras import REPORT, criterion_table, latency_table, torque_rate_table
from experiments.d_report import add_best_classical, wins_table

LABELS.update({"pd_shared": "PD tuned on the tracking composite", "pd_shared_cap": "PD tuned on the cap composite", "pd_feedforward": "PD (tracking-tuned) + inverse-dynamics feedforward",
               "pd_shared_cap_feedforward": "PD (cap-tuned) + inverse-dynamics feedforward", "best_classical": "Best classical controller of the family", "oracle_pd": "Oracle around the PD (privileged ceiling)",
               "pd_residual_v3": "Residual by actor-critic through the plant", "distill_v3_gain_ext": "Distilled impedance student (free-space fix)", "ideal_residual": "TAM-style ideal-robot residual (re-implementation)",
               "distill_gain_ext": "Distilled student trained on the sphere plant (transferred)"})
_metrics_path = Path(_os.environ.get("LLC_METRICS", "runs/m10/metrics_test.json"))
_data, _groups = load(_metrics_path) if _metrics_path.exists() else ({}, {})
for _g in _groups.values():
    add_best_classical(_g)
ORDER = ["best_classical", "pd_shared", "pd_shared_cap", "pd_feedforward", "pd_shared_cap_feedforward", "oracle_pd", "pd_residual_v3", "distill_v3_gain_ext", "ideal_residual", "distill_gain_ext"]
METHODS = [(k, LABELS.get(k, k)) for k in ORDER if k in _groups.get("in_distribution", {})]
LEARNED = [k for k in ("pd_residual_v3", "distill_v3_gain_ext", "ideal_residual", "distill_gain_ext") if k in _groups.get("in_distribution", {})]

CRITERION_SECTION = ("<h2>The success criterion</h2>\n<p>Every family and held-out group composite of each learned method against the best classical controller of that family (the lower cap composite among the two tuned PDs and their feedforward variants).</p>\n" + criterion_table(_groups, LEARNED)) if _groups else ""
WINS_SECTION = ("<h2>Where the learned controllers win and lose</h2>\n" + wins_table(_data, METHODS, "best_classical")) if _data else ""
LATENCY_SECTION = ("<h2>Compute latency</h2>\n" + latency_table(_groups, LEARNED)) if _groups else ""
SMOOTH_SECTION = ("<h2>Smoothness</h2>\n" + torque_rate_table(_groups, [k for k, _ in METHODS])) if _groups else ""
_videos = REPORT / "data" / "videos.html"
VIDEO_SECTION = ("<h2>Representative episodes</h2>\n" + _videos.read_text()) if _videos.exists() else ""

NARRATIVE = {
    "question": """<p>Can one learned low-level controller be competitive or better than the best classical baseline on every family and held-out condition at once, on the gripper plant? The deep dives and Checkpoint 1 showed the learned controllers winning free space and contact separately; this milestone implements the approaches that earned their place, adds the closest published method as a learned baseline, and reads everything against the strongest classical set under a pre-registered criterion (ADR 0010).</p>""",
    "setup": """<p><strong>Learned methods, three seeds each.</strong> The residual trained by the actor-critic through the plant (the D3 recipe on the v3 gains). The impedance student distilled from the privileged oracle around that residual, gain-residual parameterisation with the external-torque input, with the free-space fix: the teacher drives only in the first DAgger iteration and the decisions of the free-space families weigh three times those of the contact families in the label loss, twelve iterations. A TAM-style ideal-robot residual (after Son et al., CoRL 2026): a residual on the PD trained supervised on free-space episodes of the training split with a smooth random external joint torque injected in half of them, the teacher torque being the one the sampled perturbed plant needs to produce the nominal robot's acceleration under the same command (the plant's inverse dynamics, privileged), Huber loss, three iterations of 48 episodes driven by the current student; a MuJoCo re-implementation without TAM's multi-robot pretraining; the ideal torque is clipped to the actuator limits and corrections above 30 Nm are dropped as infeasible (ADR 0010 amendment). Its first-iteration checkpoint is the one in the tables (by the selection rule the plain PD would be chosen, see the findings). The student trained on the sphere plant (report 13) is kept in the tables as transferred, unchanged.</p>
<p><strong>Classical set.</strong> The PD tuned on the tracking composite and a PD tuned on the cap composite, both by the Milestone 1 CMA-ES procedure with the same budget on plant v3, and the inverse-dynamics feedforward variant of each. The best of the four per family is the reference of every paired comparison and of the success criterion; the privileged oracle around the tracking-tuned PD is the ceiling.</p>
<p><strong>Benchmark.</strong> Protocol v3 (plant v3; 16 test cases per family; the held-out workspace, speed, payload, instance and compliant-surface groups; the two task families), a group with every learned controller at a 5 ms compute latency, torque-rate RMS as a column. Criterion: within 5% of the best classical or better on every family and group composite, better on the three contact families and both task-success rates, three seeds with intervals excluding zero where a win is claimed, no divergence at 5 ms.</p>""",
    "extra_sections": [s for s in (CRITERION_SECTION, WINS_SECTION, LATENCY_SECTION, SMOOTH_SECTION, VIDEO_SECTION) if s],
    "findings": """<ol>
<li><strong>The distilled student with the free-space fix is the controller the milestone asked for, with one exception.</strong> Against the best classical controller of each family (the tracking-tuned PD on hold, policy-like and step targets, the feedforward PD on free motion and the task family, the cap-tuned PD and its feedforward variant on the two contact families) its cap composites are 1.03 on hold, 0.96 on policy-like targets, 0.82 on steps, 0.70 on press-and-slide, 0.40 on blocked targets and 0.76 on the task family, as ratios; on the held-out groups 1.02 (workspace), 0.80 and 0.78 (speeds), 0.48 (3 kg payload), 0.61 (instance deviations), 0.52 and 0.65 (compliant surfaces), 0.91 (tasks). The one miss is free motion at 2.02: the feedforward PD tracks at 4.9 mrad against the student's 11.9 (the tracking-tuned PD without feedforward: 8.8). Of the 33 family-and-group rows of the criterion table 27 are met; the six misses are all the free-motion family (in-distribution +102%, held-out workspace +32%, speed x1.5 +138%, x2 +142%, payload 3 kg +7%, instance deviations +67%). In-distribution mean 2.65 against 3.95 for the best classical and 3.06 for the privileged oracle; the actor-critic residual meets 23 rows, the TAM-style residual and the transferred student 24 each.</li>
<li><strong>The free-space fix held.</strong> The student keeps the actor-critic residual's free space (hold 1.80 against 1.75, policy-like 2.24 against 2.20, step 2.71 against 2.83) while taking the blocked composite from 11.4 to 4.2 (force above the cap 3.2 against 12.7 N, drift 2 mm, moving 7% of the time, apparent stiffness 379 N/m, release reaction 0.27 s against 1.53) and the task family from 3.64 to 3.31. The D6 recipe on the sphere plant had given up 20 to 40% of free space for the same contact behaviour.</li>
<li><strong>Contact.</strong> On blocked targets the student is below the privileged oracle's composite (4.15 against 4.73), with a lower sustained peak (48 against 75 N) and the release reaction at 0.27 s against 0.05; on press-and-slide it holds 2.9 N above the cap against 9.1 for the best classical but presses at 6 N, below the 7 N floor (deficit 3.0 against 0.4), the price of the cap law's 5 N floor in the teacher; on the task family 0.7 N above the cap against 10.4 and a sustained peak of 12 N against 39.</li>
<li><strong>Tasks: parity in success, gentler contact.</strong> Push success 31% for the student and the best classical alike (the box's yaw is the failure for every controller), place success 100% for both; the student places with a 5 N peak against 14 N and tracks the lift as the PD does (8.4 mrad). The task-success half of the criterion (better on both rates) is therefore not met: parity, not a win. The TAM-style residual is the best pusher of the table (54%) and the best at hold (0.69 of the best classical) and lift tracking (6.3 mrad), the residual-only controllers the gentlest placers.</li>
<li><strong>The actor-critic residual alone is competitive but not across the board.</strong> It wins steps, press-and-slide and the task family (0.86, 0.78, 0.84) and every held-out group except the compliant surfaces (1.04 and 1.23), is at parity on hold and the workspace, and loses blocked targets (1.10) and free motion (2.02). Its selected checkpoint is a late contact-stage iteration; its stage-1 optimum tracked free motion twice as well on validation but scored worse under the cap.</li>
<li><strong>The TAM-style ideal-robot residual compensates contact as model error.</strong> Its first iteration improves hold (5.5 against 8.1 mrad) and free motion (7.8 mrad) over the tracking-tuned PD and wins pushing, and doubles the blocked composite (21.0 against 10.4; 55 N above the cap, apparent stiffness 1700 N/m) and loses every held-out group with contact; by the selection rule the plain PD would have been its checkpoint. Under this protocol an ideal-robot residual is the wrong tool for contact and a good one for free-space adaptation.</li>
<li><strong>Plant transfer.</strong> The student trained on the sphere plant, run unchanged, is at 2.82 in-distribution, 0.37 on blocked targets and 0.60 on the compliant surfaces, but loses hold (1.41) and free motion (2.80): on the new plant the native student is the better controller in free space while matching it in contact.</li>
<li><strong>Realism checks.</strong> With a 5 ms compute latency no learned controller diverges; the student's in-distribution mean moves from 2.65 to 2.73, the residual's from 3.80 to 3.95. Torque-rate RMS: the student is as rough as the stiff PD in free motion (129 against 115 Nm/s) and the residual smoother (83).</li>
</ol>""",
    "caveats": """<ul>
<li>The best classical controller is chosen per family by the cap composite on the test cases themselves, which favours the classical side of every comparison; the learned controllers are selected once, on the 32 validation cases.</li>
<li>The TAM-style residual is our re-implementation (no multi-robot pretraining, 100 ms history instead of 12 s, labels clipped and bounded); the table carries its first iteration because the selection rule would return the plain PD. It is a baseline for the idea, not a reproduction of the paper's numbers.</li>
<li>The classical PDs are tuned by the Milestone 1 procedure on four cases per family; a larger tuning budget or a per-family gain set would raise the classical bar.</li>
<li>Light sliding contact detaches on this plant for every controller at the forces the cap allows (report 14), so the contact-loss metric of the two sliding families measures the simulator's sliding dynamics as much as the controller; the press deficit counts force below 7 N, which the capped controllers often sit at.</li>
<li>The latency check models compute latency only (decisions take effect 5 ms after their observation); actuation delay, observation delay and the 10 ms decision period are as in the rest of the protocol.</li>
<li>Three seeds per learned method; the oracle is privileged (surface and payload) and is a ceiling, not a baseline.</li>
</ul>""",
    "next": """<ul>
<li>Checkpoint 2 (report 16) states the verdict of the pre-registered criterion and what remains.</li>
<li>If the criterion is missed on free space only: tune the free-space weight and the number of student-driven iterations, or the two-part architecture (the residual frozen plus a contact head).</li>
<li>The press deficit of the learned controllers on the press-and-slide family: a teacher with the press floor enforced (f_min 7 N) would move the students into the band.</li>
</ul>""",
}
